_INET, SOCK_STREAM, SOL_TCP ) ) < 0 )				throw new Exception("failed to socket_create: ".socket_strerror(socket_last_error($this->sock)));			else {				$this->log->debug("listen:".$this->addr.":".$this->port);				socket_set_option( $this->sockServer, SOL_SOCKET, SO_REUSEADDR, 1);				if( ( $ret = socket_bind ( $this->sockServer, $this->addr, $this->port ) ) < 0 )					throw new Exception("failed to socket_bind: ".socket_strerror(socket_last_error($this->sock)));				else {					if( ( $ret = socket_listen( $this->sockServer, 10 ) ) < 0 )						throw new Exception("failed to socket_listen: ".socket_strerror(socket_last_error($this->sock)));					else {						//socket_getsockname($this->sockServer, $this->addr, $this->port);						//socket_set_nonblock($this->sockServer);						set_time_limit(0);						$this->log->debug("run go in the do, john");						declare(ticks=10000) {							do {$this->check();} while(true);						}					}				}				socket_close($this->sockServer);			}					} catch(Exception $err) {			$this->log->error($err);			throw $err;		}	}	private function check() {		try {			//$this->log->trace("."); !! too much write						$read = array($this->sockServer);			$nbSocketReady = socket_select($read, $write = NULL, $except = NULL, 0);			if ( $nbSocketReady === false )				throw new Exception("failed to socket_select: ".socket_strerror(socket_last_error($this->sockServer)));						if ( $nbSocketReady < 1) // 0 : no wait, null : wait until the end, else seconde timeout				continue;						$this->stream_socket = @socket_accept($this->sockServer);			if ( $this->stream_socket === false )				usleep(100);			elseif ( $this->sock >0 )				$this->accept( );			else				throw new Exception("failed to socket_accept: ".socket_strerror(socket_last_error($this->sock)));					} catch(Exception $err) {			$this->log->error($err);			throw $err;		}	}	private $cptAnswer = 0;	private function accept() {		try {			$this->log->debug("accept switch to");			DwLogger::logSwitchTo("DwSocketServerMono-".($this->cptAnswer++).".log");			$this->log->trace(".");			$this->answer();						$addr="0.0.0.0";$port="0";			socket_getsockname($this->sock, $addr, $port);			$raddr="0.0.0.0";$rport="0";			socket_getpeername($this->sock, $raddr, $rport);						$this->log->info("$addr:$port <=> $raddr:$rport");		} catch(Exception $err) {			$this->log->error($err);			throw $err;		}	}	public function answer() {		try {			$this->log->trace(".");			$request = null;			try {				$request = $this->read();			} catch (Exception $e) {				$this->log->error($e);				$response = "request-> read fatal error!";				throw $e;			}			if ( $request != null ) {				$this->log->info("new client connection request-size:".strlen($request));				try {					$reponse = $this->dwCallBack->callback($request);				} catch (Exception $e) {					$this->log->error($e);					$response = "dwCallBack->callback fatal error!";					throw $e;				}			}					} catch(Exception $err) {			$this->log->error($err);			throw $err;		}		return $response;			}}?>